//! The bundled catalog (`models.json`, generated by `cargo xtask models`) holds every upstream
//! provider and model type: counts per provider and type match the upstream data.

use std::collections::BTreeMap;
use std::path::PathBuf;

use pi_ai::Model;
use pi_ai::models::builtin_models;
use serde_json::Value;

